    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endSWS(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 10);  // UNITS
        $builder->required($o, 40);  // EPOCHS_MS
        $builder->required($o, 42);  // VALUES
        $builder->required($o, 66);  // PROVENANCE
        return $o;
    }

    public static function finishSWSBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, '$SWS');
    }
